import {uid,clone,I,point,cubic,worldPath,pathD,makePath,bounds,evaluatedPath,samples} from './core.js';
export function ensureEdges(o,previous){if(!o?.nodes)return;for(const n of o.nodes){n.nid??=uid();n.edgeId??=uid();n.edgeParents??=[];}if(previous?.nodes){const old=previous.nodes,keep=new Set(o.nodes.map(n=>n.nid));for(let i=0;i<o.nodes.length-(o.closed?0:1);i++){const a=o.nodes[i],b=o.nodes[(i+1)%o.nodes.length],start=old.findIndex(n=>n.nid===a.nid),end=old.findIndex(n=>n.nid===b.nid);if(start<0||end<0)continue;let j=(start+1)%old.length,removed=[];while(j!==end&&j!==start){if(!keep.has(old[j].nid))removed.push(old[j].edgeId,...old[j].edgeParents||[]);j=(j+1)%old.length;}if(removed.length)a.edgeParents=[...new Set([...a.edgeParents,...removed])];}}}
export function edgeSelected(n,ids){return ids.includes(n.edgeId)||(n.edgeParents||[]).some(id=>ids.includes(id));}
export function rangePaths(source,ids){if(!ids?.length)return [source];ensureEdges(source);const evaluated=evaluatedPath(source),world=samples(worldPath(source),48),area=world.reduce((v,a,i)=>{const b=world[(i+1)%world.length];return v+a.x*b.y-b.x*a.y;},0),interiorSign=source.closed?(Math.sign(area)||1):Math.sign(source.matrix[0]*source.matrix[3]-source.matrix[1]*source.matrix[2])||1;source={...evaluated,interiorSign,modifiers:(source.modifiers||[]).filter(m=>!['bend','fabricFall'].includes(m.type))};let nodes=source.nodes,flags=nodes.map(n=>edgeSelected(n,ids));if(source.closed&&flags.every(Boolean))return [source];if(source.closed){const start=flags.findIndex(f=>!f);nodes=[...nodes.slice(start+1),...nodes.slice(0,start+1)];flags=nodes.map(n=>edgeSelected(n,ids));}const runs=[];let run=[];for(let i=0;i<nodes.length-(source.closed?0:1);i++){if(flags[i]){if(!run.length)run.push(clone(nodes[i]));run.push(clone(nodes[(i+1)%nodes.length]));}else if(run.length){runs.push(run);run=[];}}if(run.length)runs.push(run);return runs.map(ns=>{delete ns[0].in;delete ns.at(-1).out;return {...source,nodes:ns,closed:false,subpaths:[]};});}
export function edgePath(source,index){const evaluated=worldPath(source),a=evaluated.nodes[index],b=evaluated.nodes[(index+1)%evaluated.nodes.length];if(!a||!b)return null;return {...evaluated,nodes:[a,b],closed:false,subpaths:[]};}
export function nearestEdge(source,p,tolerance=6){if(!source?.nodes||source.component)return null;ensureEdges(source);const w=worldPath(source);let best=null;for(let i=0;i<w.nodes.length-(w.closed?0:1);i++){const a=w.nodes[i],b=w.nodes[(i+1)%w.nodes.length],index=source.nodes.findIndex(n=>n.edgeId===a.edgeId||(a.edgeParents||[]).includes(n.edgeId));if(index<0)continue;for(let k=0;k<=36;k++){const t=k/36,q=cubic(a,b,t),d=Math.hypot(p.x-q.x,p.y-q.y);if(d<=tolerance&&(!best||d<best.distance))best={index,edgeId:source.nodes[index].edgeId,t,point:q,distance:d};}}return best;}
export function semanticEdges(o,definition){ensureEdges(o);o.semanticEdges??={};if(definition)for(const [name,indices]of Object.entries(definition))o.semanticEdges[name]=indices.map(i=>o.nodes[i]?.edgeId).filter(Boolean);return o;}
export function selectedRangeIds(o,name){return (o.semanticEdges?.[name]||[]).filter(id=>o.nodes.some(n=>edgeSelected(n,[id])));}
export function edgeHighlight(o,ids){return rangePaths(o,ids).map(p=>pathD(worldPath(p))).join(' ');}
